nta.declaration:
const double F = 0.1;           // frequency, unit: second

const int X = 0;
const int Y = 1;
const int Z = 2;
const int D = 2;                // dimensions: 1-x; 2-x,y; 3-x,y,z

clock tp[D], tv[D];
double ta[D];

clock ep[D], ev[D];
double ea[D];

broadcast chan syn_s, syn_d, syn_c;

/*
 tranformation between double and int
*/
const uint8_t BASE = 10;
const uint8_t EXPONENT = 1;
int32_t d2i(const double value) {
    return fint(value*pow(BASE,EXPONENT));
}
double i2d(const int32_t value) {
    return value/pow(BASE,EXPONENT);
}

/** Shielding */
import "/home/rong/Github/AutoScene/car/shield/logic_scenario.so"
{
    void open_loop_LK(double px, double py, double vx, double vy, double &ax, double &ay,
                double P, double AMINX, double AMINY, double AMAXX, double AMAXY, 
                double VMINX, double VMINY, double VMAXX, double VMAXY, 
                int lane_id, int &waypoint);

    void get_action(double tpx, double tpy, double tvx, double tvy, double &tax, double &tay,
                    double epx, double epy, double evx, double evy, double eax, double eay,
                    double P, double AMINX, double AMINY, double AMAXX, double AMAXY, 
                    double VMINX, double VMINY, double VMAXX, double VMAXY, 
                    int lane_id, int& waypoint);

    void initialize(clock &px, clock &py, int lane_id, int &temp);
};

template.declaration:
int waypoint = 0;
double ta_options[D];

int temp = 222;

void begin(){
    pv[X] = 0.1;
    //pp[X] = lane_id;
    initialize(pp[X],pp[Y], lane_id, temp);
}

void get_acce(const int32_t AMIN[D], const int32_t AMAX[D], 
              const int32_t VMIN[D], const int32_t VMAX[D]){
    open_loop_LK(pp[X],pp[Y],pv[X],pv[Y],ta_options[X],ta_options[Y], F,
                 i2d(AMIN[X]), i2d(AMIN[Y]), i2d(AMAX[X]), i2d(AMAX[Y]),
                 i2d(VMIN[X]), i2d(VMIN[Y]), i2d(VMAX[X]), i2d(VMAX[Y]), 
                 lane_id, waypoint);
}

bool shield(int tax, int tay){
    int ta_options_int[D];

    ta_options_int[X] = d2i(ta_options[X]);
    ta_options_int[Y] = d2i(ta_options[Y]);

    if(ta_options_int[X] == tax && 
       ta_options_int[Y] == tay){
        return true;
    }

    return false;
}

nta.system:
clock time;

const int32_t AMAX_EGO[D] = {d2i(0.5), d2i(0.5)};
const int32_t AMIN_EGO[D] = {d2i(-0.2), d2i(-0.2)};
const int32_t VMAX_EGO[D] = {d2i(2.0), d2i(2.0)};
const int32_t VMIN_EGO[D] = {d2i(-1.0), d2i(-1.0)};
const int INIT_LANE_EGO = 30626;
const int32_t AMAX_TEST[D] = {d2i(0.5), d2i(0.5)};
const int32_t AMIN_TEST[D] = {d2i(-0.2), d2i(-0.2)};
const int32_t VMAX_TEST[D] = {d2i(3.0), d2i(3.0)};
const int32_t VMIN_TEST[D] = {d2i(-1.0), d2i(-1.0)};
const int INIT_LANE_TEST = 30624;

test = Kinematics(tp,tv,ta);
test_control = LKController(tp, tv, ta, AMAX_TEST, AMIN_TEST, VMAX_TEST, VMIN_TEST, INIT_LANE_TEST);
ego = Kinematics(ep,ev,ea);
ego_control = LKController(ep, ev, ea, AMAX_EGO, AMIN_EGO, VMAX_EGO, VMIN_EGO, INIT_LANE_EGO);
// List one or more processes to be composed into a system.
system Timer, ego, ego_control, test, test_control;
